alter table public.execution_orders add constraint execution_orders_current_state_check check(current_state in('PROPOSED','SAFETY_PASSED','BLOCKED','SUBMITTING','SUBMITTED','ACKNOWLEDGED','PARTIALLY_FILLED','FILLED','CANCELLED','REJECTED','EXPIRED','RECONCILIATION_REQUIRED','CLOSED','MANUAL_INTERVENTION'));
alter table public.execution_order_events add constraint execution_order_events_previous_state_check check(previous_state is null or previous_state in('PROPOSED','SAFETY_PASSED','BLOCKED','SUBMITTING','SUBMITTED','ACKNOWLEDGED','PARTIALLY_FILLED','FILLED','CANCELLED','REJECTED','EXPIRED','RECONCILIATION_REQUIRED','CLOSED','MANUAL_INTERVENTION'));
alter table public.execution_order_events add constraint execution_order_events_next_state_check check(next_state in('PROPOSED','SAFETY_PASSED','BLOCKED','SUBMITTING','SUBMITTED','ACKNOWLEDGED','PARTIALLY_FILLED','FILLED','CANCELLED','REJECTED','EXPIRED','RECONCILIATION_REQUIRED','CLOSED','MANUAL_INTERVENTION'));
create trigger execution_control_revisions_immutable before update or delete on public.execution_control_revisions for each row execute function public.prevent_execution_history_mutation();
